import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

// ⚠️ API KEY'i buraya yapıştır (Tırnakların içine)
const API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [filtreKategori, setFiltreKategori] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  // AI ve Modal State'leri
  const [seciliMekan, setSeciliMekan] = useState(null);
  const [aiCevap, setAiCevap] = useState("");
  const [loading, setLoading] = useState(false);

  // Veriyi Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("API Hatası:", err));
  }, []);

  // --- ✅ DÜZELTİLMİŞ SÜRE HESAPLAMA ---
  const toplamSure = favoriler.reduce((toplam, mekan) => {
    const sureSayi = parseInt(mekan.sure);
    return toplam + (isNaN(sureSayi) ? 0 : sureSayi);
  }, 0);

  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // Ekle / Çıkar Fonksiyonu
  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => Number(f.id) === Number(mekan.id));
    if (varMi) {
      setFavoriler(favoriler.filter(f => Number(f.id) !== Number(mekan.id)));
    } else {
      setFavoriler([...favoriler, mekan]);
    }
  };

  // AI Fonksiyonu
  const askAI = async (mekan) => {
    if(!API_KEY || API_KEY.includes("BURAYA")) { alert("Lütfen kodun içine API Key yapıştırın!"); return; }

    setLoading(true);
    setAiCevap("");
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-pro"});
      const prompt = `Antalya'daki "${mekan.ad}" hakkında turistler için 2 kısa, ilgi çekici cümle kur.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) {
      setAiCevap("Bağlantı hatası oluştu.");
    } finally {
      setLoading(false);
    }
  };

  const filtrelenmisMekanlar = mekanlar.filter(m => {
    const katUygun = filtreKategori === 'Hepsi' || m.kategori === filtreKategori;
    const sureUygun = !maxSure || parseInt(m.sure) <= parseInt(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="app-container">
      <style>{`
        :root { --primary: #0aa1a1; --accent: #a9e6dd; --bg: #f3f4f6; --card-bg: #ffffff; --text: #1f2937; }
        body { margin: 0; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: var(--bg); color: var(--text); }

        .app-container { max-width: 1200px; margin: 0 auto; padding: 40px 20px; }

        /* Header & Stats Bar */
        .header-section { margin-bottom: 40px; }
        .stats-bar {
          display: flex; justify-content: space-between; align-items: center;
          background: linear-gradient(135deg, var(--primary), #1f6f9c);
          color: white; padding: 25px 40px; border-radius: 20px;
          box-shadow: 0 10px 25px -5px rgba(30, 58, 138, 0.25);
        }
        .stat-item h2 { margin: 0; font-size: 32px; font-weight: 700; }
        .stat-item p { margin: 0; opacity: 0.8; font-size: 14px; text-transform: uppercase; letter-spacing: 1px; }

        /* Filters */
        .controls { display: flex; gap: 20px; margin-top: 30px; flex-wrap: wrap; }
        .input-group { flex: 1; min-width: 200px; }
        .input-styled {
          width: 100%; padding: 15px 20px; border: 2px solid #e5e7eb; border-radius: 12px;
          font-size: 16px; outline: none; transition: border-color 0.3s;
          box-sizing: border-box; background: white;
        }
        .input-styled:focus { border-color: var(--accent); }

        /* Grid */
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 30px; margin-top: 40px; }

        /* Cards */
        .card {
          background: var(--card-bg); border-radius: 20px; overflow: hidden;
          box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
          transition: transform 0.3s ease;
          display: flex; flex-direction: column;
          border: 1px solid #f0f0f0;
        }
        .card:hover { transform: translateY(-8px); box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1); }

        .card-img-wrap { height: 200px; overflow: hidden; position: relative; }
        .card-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }

        /* HOVER EFEKTİ İÇİN STİLLER */
        .card-img-wrap:hover .card-img { transform: scale(1.1); }

        .hover-info {
          position: absolute; top: 0; left: 0; right: 0; bottom: 0;
          background: rgba(10, 161, 161, 0.9); /* Tema rengiyle uyumlu koyu perde */
          color: white;
          display: flex; align-items: center; justify-content: center;
          text-align: center; padding: 20px;
          opacity: 0; transition: all 0.3s ease;
          font-weight: 500; font-size: 15px; line-height: 1.5;
        }
        .card-img-wrap:hover .hover-info { opacity: 1; }

        .badge {
          position: absolute; top: 15px; right: 15px; z-index: 10;
          background: rgba(255,255,255,0.95); color: var(--primary);
          padding: 6px 12px; border-radius: 20px; font-weight: 700; font-size: 12px;
        }

        .card-body { padding: 20px; flex-grow: 1; position: relative; z-index: 5; background: white; }
        .card-title { font-size: 20px; font-weight: 700; margin: 0 0 10px 0; color: #111; }
        .card-info { display: flex; align-items: center; gap: 15px; color: #6b7280; font-size: 14px; }

        /* Buttons */
        .card-actions { padding: 20px; background: #f9fafb; display: flex; gap: 10px; border-top: 1px solid #f3f4f6; }
        .btn {
          flex: 1; padding: 12px; border: none; border-radius: 10px; font-weight: 600; cursor: pointer;
          transition: all 0.2s; display: flex; justify-content: center; align-items: center; gap: 6px; font-size: 14px;
        }
        .btn-primary { background: var(--primary); color: white; }
        .btn-primary:hover { background: #1e40af; }
        .btn-outline { background: white; border: 2px solid #e5e7eb; color: var(--text); }
        .btn-outline:hover { border-color: var(--primary); color: var(--primary); }
        .btn-active { background: #ef4444; color: white; } 

        /* Modal */
        .modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 1000; backdrop-filter: blur(5px); }
        .modal-content { background: white; padding: 30px; border-radius: 24px; width: 90%; max-width: 500px; position: relative; }
        .ai-response-box { background: #eff6ff; border-left: 4px solid var(--accent); padding: 15px; margin-top: 20px; border-radius: 8px; font-size: 15px; line-height: 1.5; }
      `}</style>

      {/* --- HEADER --- */}
      <div className="header-section">
        <div className="stats-bar">
          <div className="stat-item">
            <p>Antalya Rota Planlayıcı</p>
            <h2>Gezilecek Yerler</h2>
          </div>
          <div className="stat-item" style={{textAlign: 'right'}}>
            <p>Toplam Rota Süresi</p>
            <h2>{saat} sa {dakika} dk</h2>
          </div>
        </div>

        {/* --- KONTROLLER --- */}
        <div className="controls">
          <div className="input-group">
            <select className="input-styled" value={filtreKategori} onChange={(e) => setFiltreKategori(e.target.value)}>
              <option value="Hepsi">Tüm Kategoriler</option>
              <option value="Tarih">🏛 Tarih</option>
              <option value="Doğa">🌲 Doğa</option>
              <option value="Eğlence">🎢 Eğlence</option>
            </select>
          </div>
          <div className="input-group">
            <input type="number" className="input-styled" placeholder="Maks. Süre (dk)" value={maxSure} onChange={(e) => setMaxSure(e.target.value)} />
          </div>
        </div>
      </div>

      {/* --- KARTLAR --- */}
      <div className="grid">
        {filtrelenmisMekanlar.map((mekan) => {
          const favorideMi = favoriler.some(f => Number(f.id) === Number(mekan.id));

          return (
            <div key={mekan.id} className="card">
              <div className="card-img-wrap">
                {/* 1. Resim ve Hata Koruması */}
                <img 
                  src={mekan.resim} 
                  alt={mekan.ad} 
                  className="card-img" 
                  onError={(e) => {
                    e.target.onerror = null; 
                    e.target.src = "https://via.placeholder.com/600x400?text=Gorsel+Yok";
                  }}
                />
                <span className="badge">{mekan.kategori}</span>

                {/* 2. Hover (Perde) Efekti */}
                <div className="hover-info">
                  <p>{mekan.aciklama}</p>
                </div>
              </div>

              <div className="card-body">
                <h3 className="card-title">{mekan.ad}</h3>
                <div className="card-info">
                  <span>📍 {mekan.bolge}</span>
                  <span>⏱ {mekan.sure} dk</span>
                </div>
              </div>

              <div className="card-actions">
                <button className="btn btn-outline" onClick={() => { setSeciliMekan(mekan); askAI(mekan); }}>
                  ✨ AI Bilgi
                </button>

                <button className={`btn ${favorideMi ? 'btn-active' : 'btn-primary'}`} onClick={() => toggleFavori(mekan)}>
                  {favorideMi ? 'Rotadan Çıkar' : 'Rotaya Ekle +'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* --- MODAL --- */}
      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2 style={{marginTop:0}}>{seciliMekan.ad}</h2>
            <p>{seciliMekan.aciklama}</p>
            <div className="ai-response-box">
              {loading ? "🤖 Yapay zeka yazıyor..." : aiCevap || "Cevap bekleniyor..."}
            </div>
            <button className="btn btn-primary" style={{marginTop: '20px', width: '100%'}} onClick={() => setSeciliMekan(null)}>
              Kapat
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
